import{_ as t,o as r,c as e,a2 as d}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"نظام ضمان «طريق لكل إنسان»","description":"","frontmatter":{},"headers":[],"relativePath":"ar/08-人人有路保障体系.md","filePath":"ar/08-人人有路保障体系.md","lastUpdated":null}'),l={name:"ar/08-人人有路保障体系.md"};function o(i,a,h,n,s,p){return r(),e("div",null,[...a[0]||(a[0]=[d('<h1 id="نظام-ضمان-«طريق-لكل-إنسان»" tabindex="-1">نظام ضمان «طريق لكل إنسان» <a class="header-anchor" href="#نظام-ضمان-«طريق-لكل-إنسان»" aria-label="Permalink to &quot;نظام ضمان «طريق لكل إنسان»&quot;">​</a></h1><table tabindex="0"><thead><tr><th>العنصر</th><th>المحتوى</th></tr></thead><tbody><tr><td>رقم الوثيقة</td><td>08</td></tr><tr><td>الوحدة</td><td>المبادئ العامة والإعدادات الأساسية</td></tr><tr><td>الكلمات المفتاحية</td><td>طريق لكل إنسان، نظام الضمان، خط التطور الأدنى، الفئات الضعيفة، المنفعة العامة</td></tr></tbody></table><h2 id="أولاً-التعريف-الأساسي-لـ«طريق-لكل-إنسان»" tabindex="-1">أولاً: التعريف الأساسي لـ«طريق لكل إنسان» <a class="header-anchor" href="#أولاً-التعريف-الأساسي-لـ«طريق-لكل-إنسان»" aria-label="Permalink to &quot;أولاً: التعريف الأساسي لـ«طريق لكل إنسان»&quot;">​</a></h2><p>«طريق لكل إنسان» هو أحد الأهداف الاجتماعية الأساسية لحضارة التكافل المرساة، ويعني ضمان أن يحصل كل كائن في هنغ يوانتشو — بغض النظر عن عرقه أو أصله أو موهبته أو مرتبته أو حالته المالية — على مسار تطور يناسبه، وتتاح له فرصة تحقيق ترقي المرتبة وإكمال الحياة بجهوده الخاصة. «امتلاك الطريق» لا يعني فقط وجود طرق زراعة يتعلمها، بل أيضاً وجود موارد يستخدمها وموجهين يسألهم وبيئة يزرع فيها ومؤسسات يعتمد عليها.</p><p>«طريق لكل إنسان» و«من عمل أكثر نال أكثر» هما الركيزتان لنظام التوزيع في الحضارة التكافلية. الأول يحل مشكلة «الكفاءة»، محفزاً الأقوياء على خلق مزيد من القيمة؛ والثاني يحل مشكلة «العدالة»، ضامناً ألا يُتخلى عن الضعفاء من قبل النظام التطوري. يتكامل الاثنان، ولا غنى عن أحدهما للآخر. دون «طريق لكل إنسان»، يتحول «من عمل أكثر نال أكثر» إلى قانون الغاب؛ ودون «من عمل أكثر نال أكثر»، يتحول «طريق لكل إنسان» إلى مساواة مطلقة.</p><h2 id="ثانياً-ضرورة-«طريق-لكل-إنسان»" tabindex="-1">ثانياً: ضرورة «طريق لكل إنسان» <a class="header-anchor" href="#ثانياً-ضرورة-«طريق-لكل-إنسان»" aria-label="Permalink to &quot;ثانياً: ضرورة «طريق لكل إنسان»&quot;">​</a></h2><p>يقوم إنشاء نظام ضمان «طريق لكل إنسان» على الإدراكات العميقة التالية:</p><h3 id="_2-1-حق-التطور-هو-أكثر-الحقوق-الحيوية-جوهرية" tabindex="-1">2.1 حق التطور هو أكثر الحقوق الحيوية جوهرية <a class="header-anchor" href="#_2-1-حق-التطور-هو-أكثر-الحقوق-الحيوية-جوهرية" aria-label="Permalink to &quot;2.1 حق التطور هو أكثر الحقوق الحيوية جوهرية&quot;">​</a></h3><p>في حضارات الزراعة، حق التطور ليس حقاً تنموياً فحسب، بل حق بقاء أيضاً. فعند مواجهة مخاطر الكون المختلفة (كتموجات المستويات وعواصف الطاقة وغزوات الأعراق الغريبة)، تكون احتمالية بقاء الكائنات ذات المراتب الدنيا أقل بكثير من الكائنات ذات المراتب العليا. لذلك، فإن ضمان وجود مسار تطوري لكل كائن هو في جوهره ضمان حق البقاء الأساسي لكل كائن.</p><h3 id="_2-2-اختلافات-المواهب-الأولية-يجب-ألا-تحدد-مصير-التطور" tabindex="-1">2.2 اختلافات المواهب الأولية يجب ألا تحدد مصير التطور <a class="header-anchor" href="#_2-2-اختلافات-المواهب-الأولية-يجب-ألا-تحدد-مصير-التطور" aria-label="Permalink to &quot;2.2 اختلافات المواهب الأولية يجب ألا تحدد مصير التطور&quot;">​</a></h3><p>توجد اختلافات هائلة في المواهب الأولية لكل كائن (الموهبة العرقية والخلفية العائلية ومستوى الميلاد والقابلية الفطرية وغيرها). في عصر الافتراسية، غالباً ما تضخمت هذه الاختلافات لتصبح هوة لا يمكن عبورها — فكائنات الأصول الجيدة تحتكر الموارد الفاخرة، بينما لا تحصل كائنات الأصول السيئة حتى على طرق الزراعة الأساسية. ترى الحضارة التكافلية أن اختلافات المواهب الأولية موجودة موضوعياً، لكنها يجب ألا تصبح العامل الوحيد الذي يحدد مصير التطور. دور المؤسسات هو تحديداً تعويض هذه الاختلافات الأولية، بما يمنح كل كائن فرصة تغيير مصيره بالجهد المكتسب.</p><h3 id="_2-3-الأفراد-المتروكون-خسارة-محتملة-للحضارة" tabindex="-1">2.3 الأفراد المتروكون خسارة محتملة للحضارة <a class="header-anchor" href="#_2-3-الأفراد-المتروكون-خسارة-محتملة-للحضارة" aria-label="Permalink to &quot;2.3 الأفراد المتروكون خسارة محتملة للحضارة&quot;">​</a></h3><p>يمتلك كل كائن إمكانات تطورية؛ وكثيرون منهم يفتقرون فقط إلى المسارات والموارد المناسبة. فكائن يعاني في القاع قد يظهر موهبة مذهلة بعد حصوله على نظام زراعة مناسب؛ وفرد يعتبر «عديم الفائدة» ربما لم يجد فقط اتجاه التطور المناسب له. أهمية نظام ضمان «طريق لكل إنسان» تكمن في عدم التخلي عن أي متطور محتمل، وتوسيع حوض المواهب للحضارة قدر الإمكان.</p><h3 id="_2-4-التطور-الشامل-هو-أساس-الصعود-الكوني" tabindex="-1">2.4 التطور الشامل هو أساس الصعود الكوني <a class="header-anchor" href="#_2-4-التطور-الشامل-هو-أساس-الصعود-الكوني" aria-label="Permalink to &quot;2.4 التطور الشامل هو أساس الصعود الكوني&quot;">​</a></h3><p>لا يمكن للصعود الشامل للكون أن يعتمد على قلة من الأقوياء الأسمى فحسب، بل يتطلب التطور الشامل لعشرة آلاف عرق وجميع الكائنات. كفاءة شبكة المراسي ترتبط ارتباطاً إيجابياً بعدد ونوعية الكائنات المتصلة بها. فعندما يدخل مزيد من الكائنات إلى أنظمة الزراعة ويرفعون مراتبهم، يصبح تداول الطاقة وتشغيل القوانين في شبكة المراسي كلها أكثر استقراراً وكفاءة، وتتسارع عملية الصعود الكوني.</p><h2 id="ثالثاً-البنية-الهرمية-لنظام-الضمان" tabindex="-1">ثالثاً: البنية الهرمية لنظام الضمان <a class="header-anchor" href="#ثالثاً-البنية-الهرمية-لنظام-الضمان" aria-label="Permalink to &quot;ثالثاً: البنية الهرمية لنظام الضمان&quot;">​</a></h2><p>ينقسم نظام ضمان «طريق لكل إنسان» إلى أربعة مستويات، مشكلاً سلسلة ضمان كاملة من الأساسي إلى المتقدم:</p><table tabindex="0"><thead><tr><th>المستوى</th><th>الاسم</th><th>محتوى الضمان</th><th>التغطية</th></tr></thead><tbody><tr><td>المستوى الأول</td><td>الضمان الأساسي</td><td>طرق الزراعة المجانية، والحد الأدنى من تخصيص الموارد، والخدمات الطبية والتعليمية الأساسية</td><td>جميع الكائنات، دون شروط</td></tr><tr><td>المستوى الثاني</td><td>الدعم الموجّه</td><td>موارد وموجهون ودعم تقني إضافيون للفئات الضعيفة</td><td>الأفراد والأعراق ذوو المواهب الأولية الضعيفة</td></tr><tr><td>المستوى الثالث</td><td>توسيع الفرص</td><td>فرص الزراعة المتقدمة، والتبادل عبر المستويات، وحقوق المشاركة في المشاريع الخاصة</td><td>المزارعون ذوو الإمكانات والموارد غير الكافية</td></tr><tr><td>المستوى الرابع</td><td>تحفيز الإنجاز</td><td>موارد الرتب العليا، والوصول المتقدم للمراسي، والأوسمة الحضارية</td><td>المزارعون ذوو الإسهامات البارزة</td></tr></tbody></table><p>المستوى الأول «يمسك القاع»، ضامناً ألا يُتخلى عن أحد؛ والثاني «يعوض الفروق»، جابراً اختلافات المواهب الأولية؛ والثالث «يرعى المتفوقين»، مانحاً الأفراد ذوي الإمكانات مزيداً من الفرص؛ والرابع «يحفز»، مكافئاً أصحاب الإسهامات البارزة. تتدرج المستويات الأربعة خطوة بخطوة، مشكلة نظاماً كاملاً للضمان والتحفيز.</p><h2 id="رابعاً-محتويات-الضمان-الأساسي-المحددة" tabindex="-1">رابعاً: محتويات الضمان الأساسي المحددة <a class="header-anchor" href="#رابعاً-محتويات-الضمان-الأساسي-المحددة" aria-label="Permalink to &quot;رابعاً: محتويات الضمان الأساسي المحددة&quot;">​</a></h2><p>الضمان الأساسي هو جوهر نظام «طريق لكل إنسان»، ويشمل تحديداً المحتويات التالية:</p><h3 id="_4-1-ضمان-طرق-الزراعة" tabindex="-1">4.1 ضمان طرق الزراعة <a class="header-anchor" href="#_4-1-ضمان-طرق-الزراعة" aria-label="Permalink to &quot;4.1 ضمان طرق الزراعة&quot;">​</a></h3><p>الطرق الأساسية لأنظمة الزراعة الأصلية الثلاثمائة مفتوحة مجاناً لجميع الكائنات، دون أي شروط. يمكن لكل كائن اختيار نظام زراعة يناسبه بحرية، دون دفع رسوم أو الانضمام لطوائف محددة أو الخضوع لفحص أهلية. توفر شبكة المراسي تقييم توافق الأنظمة، مساعدةً المزارعين على إيجاد المسار الأنسب لهم.</p><h3 id="_4-2-ضمان-موارد-الزراعة" tabindex="-1">4.2 ضمان موارد الزراعة <a class="header-anchor" href="#_4-2-ضمان-موارد-الزراعة" aria-label="Permalink to &quot;4.2 ضمان موارد الزراعة&quot;">​</a></h3><p>عبر نظام العقود المرتبطة بالإنتاج والتخصيص العام للموارد، يُضمن لكل كائن الحصول على الموارد اللازمة لاستمرار الزراعة الأساسية. يشمل التخصيص الأساسي للموارد: الحد الأدنى من إمداد الطاقة، وحبوب الزراعة الأساسية، وحقوق استخدام المعدات العامة للزراعة. وبالنسبة للمستويات التي تعاني ندرة الموارد، يجري تعديل موارد عبر المستويات عبر شبكة المراسي.</p><h3 id="_4-3-ضمان-بيئة-الزراعة" tabindex="-1">4.3 ضمان بيئة الزراعة <a class="header-anchor" href="#_4-3-ضمان-بيئة-الزراعة" aria-label="Permalink to &quot;4.3 ضمان بيئة الزراعة&quot;">​</a></h3><p>أنشأت الحضارة التكافلية أماكن زراعة عامة في كل كوكب ومستوى، تشمل غرف الزراعة العامة ومناطق ضبط تركيز الطاقة وغرف استيعاب القوانين وغيرها. هذه الأماكن مفتوحة لجميع الكائنات مجاناً أو بأسعار منخفضة، بما يضمن أن يكون لدى حتى أفقر المزارعين بيئة زراعة مناسبة.</p><h3 id="_4-4-ضمان-إرشاد-الموجهين" tabindex="-1">4.4 ضمان إرشاد الموجهين <a class="header-anchor" href="#_4-4-ضمان-إرشاد-الموجهين" aria-label="Permalink to &quot;4.4 ضمان إرشاد الموجهين&quot;">​</a></h3><p>إنشاء شبكة موجهين بين الأعراق، حيث يقع على المزارعين المتقدمين واجب تقديم الإرشاد الأساسي للمزارعين المبتدئين. يمكن لكل مزارع مبتدئ طلب مطابقة موجه عبر شبكة المراسي، والحصول مجاناً على الإجابة الأساسية عن الأسئلة ونصائح الزراعة. وبالنسبة للمزارعين ذوي الصعوبات الخاصة، يقدم إرشاد موجّه فردي.</p><h3 id="_4-5-ضمان-العلاج-وإعادة-التأهيل" tabindex="-1">4.5 ضمان العلاج وإعادة التأهيل <a class="header-anchor" href="#_4-5-ضمان-العلاج-وإعادة-التأهيل" aria-label="Permalink to &quot;4.5 ضمان العلاج وإعادة التأهيل&quot;">​</a></h3><p>يقدم النظام الطبي التكافلي للمزارعين العلاج الطبي الأساسي المجاني وخدمات إعادة التأهيل من انحرافات الزراعة. الإصابات أثناء الزراعة والجنون الانحرافي واضطرابات الطاقة وغيرها من الحالات تحصل جميعها على علاج ودعم إعادة تأهيل في الوقت المناسب، بما يضمن ألا يفقد المزارعون قدرتهم التطورية بسبب الحوادث.</p><h2 id="خامساً-مستهدفو-الدعم-الموجّه-وطرقه" tabindex="-1">خامساً: مستهدفو الدعم الموجّه وطرقه <a class="header-anchor" href="#خامساً-مستهدفو-الدعم-الموجّه-وطرقه" aria-label="Permalink to &quot;خامساً: مستهدفو الدعم الموجّه وطرقه&quot;">​</a></h2><p>يستهدف الدعم الموجّه الفئات الضعيفة التالية:</p><ul><li><strong>الأفراد ذوو المواهب المنخفضة</strong>: الأفراد ذوو القابلية الفطرية الضعيفة وبطء التقدم في الزراعة يحصلون على تخصيص إضافي للموارد وإرشاد فردي</li><li><strong>الأعراق الفقيرة</strong>: الأعراق التي تعاني ندرة شاملة في الموارد وانخفاض مستوى التطور تحصل على دعم موجّه من صندوق التنمية العرقية</li><li><strong>مجموعات ما بعد الكوارث</strong>: المجموعات التي فقدت منازلها ومواردها بسبب كوارث المستويات والحروب وغيرها تحصل على إغاثة عاجلة ودعم إعادة الإعمار</li><li><strong>المزارعون ذوو الإعاقات</strong>: المزارعون ذوو الإعاقات الجسدية أو النفسية لأسباب شتى يحصلون على معدات مساعدة خاصة للزراعة وخطط زراعة مخصصة</li><li><strong>الأحياء الشاذة</strong>: الأحياء الشاذة التي لا تندرج في أنظمة الزراعة التقليدية تحصل على تقييم متخصص ومسارات تطور مخصصة</li></ul><p>تشمل طرق الدعم الموجّه: التخصيص الإضافي للموارد، والإرشاد الفردي الموجه، وخطط الزراعة المخصصة، وتوفير المعدات الخاصة، وفرص التبادل عبر المستويات وغيرها. الهدف من الدعم هو مساعدة الفئات الضعيفة على بلوغ المستوى التطوري الأساسي، ثم الانتقال تدريجياً إلى نظام التوزيع العادي لـ«من عمل أكثر نال أكثر».</p><h2 id="سادساً-مصادر-تمويل-وموارد-نظام-الضمان" tabindex="-1">سادساً: مصادر تمويل وموارد نظام الضمان <a class="header-anchor" href="#سادساً-مصادر-تمويل-وموارد-نظام-الضمان" aria-label="Permalink to &quot;سادساً: مصادر تمويل وموارد نظام الضمان&quot;">​</a></h2><p>يتطلب تشغيل نظام ضمان «طريق لكل إنسان» موارد وأموالاً كبيرة، تشمل مصادرها:</p><ol><li><strong>إيرادات الموارد العامة</strong>: إنتاج عروق الأرواح العامة وعروق المعادن الطاقية وحقول الأدوية وغيرها من الموارد التي تديرها الحضارة التكافلية مباشرة</li><li><strong>ضريبة تعديل المساهمات</strong>: نسبة معينة من «ضريبة تعديل المساهمات» تفرض على أصحاب المساهمات العالية، تستخدم لتشغيل نظام الضمان (نسبة تصاعدية، لا تتجاوز 30%)</li><li><strong>صندوق التنمية الحضارية</strong>: الطاقة الفائضة الناتجة عن تشغيل شبكة المراسي، يُضخ جزء منها في صندوق التنمية الحضارية</li><li><strong>إيرادات الترخيص التقني</strong>: رسوم ترخيص تقنيات هندسة القوانين المملوكة للحضارة التكافلية</li><li><strong>التبرعات والوصايا</strong>: التبرعات الطوعية من الأفراد والأعراق</li></ol><p>تدير لجنة الضمان التابعة لجمعية جمهورية عشرة آلاف عرق إيرادات ومصروفات نظام الضمان، مع الكشف الدوري عن الحسابات لجميع الكائنات، وتخضع للإشراف.</p><h2 id="الخاتمة" tabindex="-1">الخاتمة <a class="header-anchor" href="#الخاتمة" aria-label="Permalink to &quot;الخاتمة&quot;">​</a></h2><p>نظام ضمان «طريق لكل إنسان» هو حجر الأساس للعدالة الاجتماعية في حضارة التكافل المرساة. إنه يضمن أنه في حضارة تتركز على الزراعة والتطور، لا يُتخلى عن أي كائن من قبل النظام التطوري بسبب أصله أو موهبته أو فقره. «طريق لكل إنسان» ليس إقامة مساواة مطلقة، بل منح كل كائن نقطة بداية عادلة وقناة صاعدة ووعداً بعدم التخلي عنه. تحت ضمان «طريق لكل إنسان»، يمكن لكل كائن أن يجد طريقه التطوري الخاص.</p><h2 id="الوثائق-ذات-الصلة" tabindex="-1">الوثائق ذات الصلة <a class="header-anchor" href="#الوثائق-ذات-الصلة" aria-label="Permalink to &quot;الوثائق ذات الصلة&quot;">​</a></h2><ul><li>06-多劳多得分配原理 (مبادئ توزيع «من عمل أكثر نال أكثر»)</li><li>07-自生自长进化法则 (قانون النمو الذاتي والتطور الذاتي)</li><li>38-共生医疗体系 (النظام الطبي التكافلي)</li></ul>',43)])])}const b=t(l,[["render",o]]);export{_ as __pageData,b as default};
